import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import { aiObservabilitySessionsAvailability } from '../../generated/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sessionsAvailabilityLogicValues {
    hasSessions: boolean | null
    hasSessionsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sessionsAvailabilityLogicActions {
    loadSessionsAvailability: () => any
    loadSessionsAvailabilityFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSessionsAvailabilitySuccess: (
        hasSessions: boolean | null,
        payload?: any
    ) => {
        hasSessions: boolean | null
        payload?: any
    }
}

export type sessionsAvailabilityLogicType = MakeLogicType<
    sessionsAvailabilityLogicValues,
    sessionsAvailabilityLogicActions
>

/** Whether the project has sessions at all, read once while the shell is mounted. Null until it answers or if it fails. */
export const sessionsAvailabilityLogic = kea<sessionsAvailabilityLogicType>([
    path(['products', 'ai_observability', 'frontend', 'redesign', 'shell', 'sessionsAvailabilityLogic']),
    loaders({
        hasSessions: [
            null as boolean | null,
            {
                loadSessionsAvailability: async (): Promise<boolean | null> => {
                    const availability = await aiObservabilitySessionsAvailability(
                        String(ApiConfig.getCurrentProjectId())
                    )
                    return availability.hasSessions
                },
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadSessionsAvailability()
    }),
])
